import{_ as o,C as n,o as t,c as i,a2 as a,b as c,w as s,a as d,E as h,a3 as l}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"Ershu","description":"Turn private repositories into an internal wiki that people and AI can search, with links back to the source.","frontmatter":{"page_id":"home","layout":"home","title":"Ershu","description":"Turn private repositories into an internal wiki that people and AI can search, with links back to the source.","hero":{"name":"Ershu","text":"Turn several code repositories into one wiki for your team and its AI tools","tagline":"Ershu builds project documentation, code indexes, interface facts, and cross-repository relationships from current source. People use the web app, while coding agents query the same project context through MCP.","image":{"src":"/favicon.ico","alt":"Ershu logo"},"actions":[{"theme":"brand","text":"Run Ershu on one machine","link":"/en/guide/quick-start"},{"theme":"alt","text":"See the problems it solves","link":"/en/overview/use-cases"}]},"features":[{"title":"Build a wiki from current code","details":"Organize modules, workflows, and interfaces by project and repository, with citations that lead back to source."},{"title":"Understand one product across repositories","details":"Put frontend, backend, services, and shared libraries in one project instead of piecing context together by hand."},{"title":"Give AI a stable project memory","details":"Let coding agents query documents, trees, indexes, relationships, and contracts through read-only MCP tools."},{"title":"Keep it in your environment","details":"Your team manages project access, repository credentials, model channels, and storage for private code."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1786627803000}'),p={name:"en/index.md"};function u(m,e,g,f,w,b){const r=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h2 id="vibe-coding-got-faster-understanding-the-system-did-not" tabindex="-1">Vibe coding got faster. Understanding the system did not. <a class="header-anchor" href="#vibe-coding-got-faster-understanding-the-system-did-not" aria-label="Permalink to &quot;Vibe coding got faster. Understanding the system did not.&quot;">​</a></h2><p>AI can complete the code in front of it, but it may not know which service a page depends on, how a change crosses repository boundaries, or whether an old design note is still true. As a project grows, that missing context can erase the speed gained from code generation.</p><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">Context resets</p><h3>Every task starts with reading the project again</h3><p>Developers and agents keep rediscovering entry points, settings, and call paths. The same understanding work gets paid for repeatedly.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Repository blind spots</p><h3>You opened one repository, but you are changing a product</h3><p>Frontend code, APIs, messages, and schemas live apart. The current directory rarely shows the complete impact of a change.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Documentation drifts</p><h3>The wiki has an answer, but nobody knows if it is current</h3><p>Once prose falls behind the code, people go back to the maintainer and AI may treat an old explanation as a present fact.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Knowledge bottlenecks</p><h3>A few maintainers become the project search engine</h3><p>New hires, QA, product, and support teams keep asking the same questions about boundaries, workflows, and past decisions.</p></article></div><aside class="home-statement"><p class="home-statement-label">What Ershu does</p><p class="home-statement-title">It turns knowledge scattered across repositories and maintainers into shared context that can be searched, checked, and refreshed.</p><p>Ershu prepares the structure, documentation, relationships, and sources before a change begins. People and agents can make fewer guesses and verify their conclusions, while the team still decides how the code should change.</p></aside><h2 id="this-wiki-is-useful-beyond-the-engineering-team" tabindex="-1">This wiki is useful beyond the engineering team <a class="header-anchor" href="#this-wiki-is-useful-beyond-the-engineering-team" aria-label="Permalink to &quot;This wiki is useful beyond the engineering team&quot;">​</a></h2><p>One project knowledge base can serve several roles. Each person gets a suitable entry point without maintaining another copy of the system description.</p><table tabindex="0"><thead><tr><th>Who uses it</th><th>What it helps them do</th></tr></thead><tbody><tr><td>New developers</td><td>See the project shape, repository boundaries, entry points, and important workflows before diving into source</td></tr><tr><td>Maintainers</td><td>Search across repositories by exact term or meaning, then follow citations to files and lines</td></tr><tr><td>Tech leads and architects</td><td>Inspect dependencies, interface contracts, candidate change surfaces, and static runtime paths before review</td></tr><tr><td>QA engineers</td><td>Use interfaces, messages, schemas, and workflows to identify inputs, outputs, and failure paths worth testing</td></tr><tr><td>Product, support, and delivery teams</td><td>Find which modules deliver a feature without learning how to browse every repository first</td></tr><tr><td>Coding agents</td><td>Retrieve project-scoped context through read-only MCP tools and see revision, freshness, and truncation signals</td></tr></tbody></table><h2 id="beyond-the-wiki-search-relationships-contracts-and-refresh" tabindex="-1">Beyond the wiki: search, relationships, contracts, and refresh <a class="header-anchor" href="#beyond-the-wiki-search-relationships-contracts-and-refresh" aria-label="Permalink to &quot;Beyond the wiki: search, relationships, contracts, and refresh&quot;">​</a></h2><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">Search</p><h3>Search exact names when you know them, or meaning when you do not</h3><p>Keyword, semantic, and hybrid modes cover code and documents. Responses make semantic fallback visible.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Relationships</p><h3>Follow one entry point toward a cross-repository impact area</h3><p>The project graph, change-surface queries, and static runtime paths help narrow candidates before source review.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Contracts</p><h3>Pull service agreements out of the codebase</h3><p>Extract interface facts from sources such as OpenAPI, GraphQL, Protobuf, message channels, and data schemas.</p></article><article class="home-card home-card--compact"><p class="home-card-label">Refresh</p><h3>Update project facts when the code changes</h3><p>After the first full baseline, manual runs, scheduled polling, or signed webhooks can refresh trees, indexes, and relationships.</p></article></div><h2 id="one-analysis-two-ways-to-use-it" tabindex="-1">One analysis, two ways to use it <a class="header-anchor" href="#one-analysis-two-ways-to-use-it" aria-label="Permalink to &quot;One analysis, two ways to use it&quot;">​</a></h2>',10)),(t(),c(l,null,{default:s(()=>[h(r,{id:"mermaid-83",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Repos%5B%22Frontend%2C%20backend%2C%20services%2C%20and%20shared%20libraries%22%5D%20--%3E%20Worker%5B%22Read-only%20Ershu%20analysis%22%5D%0A%20%20Worker%20--%3E%20Knowledge%5B%22Documents%2C%20search%20indexes%2C%20code%20relationships%2C%20and%20contracts%22%5D%0A%20%20Knowledge%20--%3E%20Web%5B%22People%20read%2C%20search%2C%20and%20inspect%20in%20the%20web%20app%22%5D%0A%20%20Knowledge%20--%3E%20MCP%5B%22Coding%20agents%20retrieve%20context%20through%20MCP%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The web app is for browsing projects, reading the wiki, searching, exploring the graph, and following analysis runs. MCP lets a coding agent discover a project, then read documents, repository trees, symbols, relationships, and bounded sections of source. Both paths use the same stored results and project permissions.</p><h2 id="where-it-fits-and-where-it-does-not" tabindex="-1">Where it fits, and where it does not <a class="header-anchor" href="#where-it-fits-and-where-it-does-not" aria-label="Permalink to &quot;Where it fits, and where it does not&quot;">​</a></h2><p>Ershu is most useful when several repositories ship one product, the organization needs control over code and model access, and AI-assisted development is becoming everyday work. It also suits teams taking over a long-lived system or rebuilding missing project documentation.</p><p>Know these boundaries before you deploy it:</p><ul><li>Ershu is self-hosted software, not a hosted code-scanning service.</li><li>The first analysis covers every active repository in a project. Repository-specific and incremental runs come after that baseline.</li><li>Generated documents help with navigation and understanding. When they conflict with current source or tests, the source wins.</li><li>Self-hosting does not guarantee that code stays on a private network. Model requests go to the model services you configure.</li><li>The Worker does not execute arbitrary repository scripts. Optional LSP support is off by default and requires a separate review of Docker access and dependency sources.</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><div class="home-path-grid"><a class="home-path-card" href="/en/overview/use-cases"><span>Check the value first</span><strong>See whether Ershu helps your team</strong><small>Start with AI coding, internal wiki, cross-repository changes, and team handoffs.</small></a><a class="home-path-card" href="/en/guide/quick-start"><span>Run it first</span><strong>Complete a one-machine deployment</strong><small>Go from dependencies to the sign-in page with a clear check after each step.</small></a><a class="home-path-card" href="/en/guide/create-first-project"><span>Use it</span><strong>Create a project and its first wiki</strong><small>Configure models, add repositories, establish a full baseline, then check documents and search.</small></a><a class="home-path-card" href="/en/guide/connect-mcp"><span>Connect AI</span><strong>Let a coding agent read from Ershu</strong><small>Create a project-scoped key and verify access with a real tool call.</small></a></div><section class="home-final-cta"><p class="home-card-label">Test it with a real question</p><h2>Pick a question your team asks often and needs several repositories to answer.</h2><p>After the first analysis, find the answer through the wiki, search, and MCP. Reaching the right source quickly is a better test than any claim on a homepage.</p><div class="home-final-actions"><a class="VPButton medium brand" href="/en/guide/quick-start">Start deployment</a><a class="VPButton medium alt" href="/en/overview/what-is-ershu">See how Ershu works</a></div></section>',8))])}const v=o(p,[["render",u]]);export{k as __pageData,v as default};
